a__cp(A1, Rows) :-
    a__cp_c1([A1], Rows).

a__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A1]),
        (   a_c1__cp_1([[A1, X, X1]], Cond),
            packet_first(Cond, Pre, Res),
            if_commit(
                Res = none,
                (   if_commit(
                        A1 = X1,
                        (   d__cp(X1, Packet),
                            splice_extend(Packet, [A1, X, X1], [X1], OutE)
                        ),
                        OutE = []
                    ),
                    rows_concat([Pre, OutE], Env)
                ),
                (   Res = first(First),
                    a_c1__cp_2([First], OutT),
                    rows_concat([Pre, OutT], Env)
                )
            ),
            splice_extend(Env, [A1], [A1, X, X1], Rows)
        ),
        Rows = []
    ).

a_c1__cp_1([], []).
a_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [A1, X, X1]),
            if_commit(
                A1 = X,
                (   b__cp(X, Packet),
                    splice_extend(Packet, [A1, X, X1], [X], Out1)
                ),
                Out1 = []
            )
        )
    ),
    a_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

a_c1__cp_2([], []).
a_c1__cp_2([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [A1, X, X1]),
            c__cp(X, Packet),
            splice_extend(Packet, [A1, X, X1], [X], Out1)
        )
    ),
    a_c1__cp_2(Rows, Out2),
    rows_concat([Out1, Out2], Out).

b__cp(A1, Rows) :-
    member_cp(P, [[1], [2]]),
    cp_filter(P, [A1], Rows).

c__cp(A1, Rows) :-
    member_cp(P, [[1]]),
    cp_filter(P, [A1], Rows).

d__cp(A1, Rows) :-
    member_cp(P, [[3]]),
    cp_filter(P, [A1], Rows).

max__cp(A1, A2, A3, Rows) :-
    max__cp_c1([A1, A2, A3], Rows).

max__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A1, A2, A3]),
        (   if_commit(
                (   A1 = X,
                    A2 = Y,
                    A3 = X,
                    X >= Y
                ),
                Env = [[A1, A2, A3, X, Y, V1, Y1]],
                if_commit(
                    (   A1 = V1,
                        A2 = Y1,
                        A3 = Y1
                    ),
                    Env = [[A1, A2, A3, X, Y, V1, Y1]],
                    Env = []
                )
            ),
            splice_extend(Env, [A1, A2, A3], [A1, A2, A3, X, Y, V1, Y1], Rows)
        ),
        Rows = []
    ).

classify__cp(A1, A2, Rows) :-
    classify__cp_c1([A1, A2], Rows).

classify__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A1, A2]),
        (   if_commit(
                (   A1 = N,
                    A2 = neg,
                    N < 0
                ),
                Env = [[A1, A2, N, V1]],
                if_commit(
                    (   A1 = 0,
                        A2 = zero
                    ),
                    Env = [[A1, A2, N, V1]],
                    if_commit(
                        (   A1 = V1,
                            A2 = pos
                        ),
                        Env = [[A1, A2, N, V1]],
                        Env = []
                    )
                )
            ),
            splice_extend(Env, [A1, A2], [A1, A2, N, V1], Rows)
        ),
        Rows = []
    ).

